package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.knowledge.*;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;
@Component public class KnowledgeRetrieveNodeExecutor implements NodeExecutor {private final KnowledgeRetriever retriever;private final ObjectMapper mapper;public KnowledgeRetrieveNodeExecutor(KnowledgeRetriever retriever,ObjectMapper mapper){this.retriever=retriever;this.mapper=mapper;}public Set<WorkflowNodeType> supportedTypes(){return EnumSet.of(WorkflowNodeType.KNOWLEDGE_RETRIEVE,WorkflowNodeType.SEMANTIC_SEARCH);}public NodeExecutionResult execute(NodeExecutionContext c){try{JsonNode config=mapper.readTree(c.getNode().getConfigurationJson());String kb=config.path("knowledgeBaseId").asText(String.valueOf(c.getVariables().getOrDefault("knowledgeBaseId","")));if(kb.trim().isEmpty())return NodeExecutionResult.failure("KNOWLEDGE_BASE_REQUIRED",false);String query=String.valueOf(c.getVariables().getOrDefault(config.path("queryVariable").asText("query"),c.getVariables().getOrDefault("text","")));Integer version=config.has("knowledgeBaseVersion")?config.path("knowledgeBaseVersion").asInt():null;HybridRetrievalResult result=retriever.retrieve(c.getExecutionContext().getTenantId(),c.getExecutionContext().getWorkspaceId(),c.getExecutionContext().getUserId(),kb,version,query,config.has("topK")?config.path("topK").asInt():null);Map<String,Object> updates=new LinkedHashMap<>();updates.put(config.path("resultVariable").asText("retrievalResults"),mapper.convertValue(result.getChunks(),Object.class));updates.put("rerankMode",result.getRerankMode());return new NodeExecutionResult(com.hmdp.ai.domain.run.NodeRunStatus.SUCCEEDED,mapper.valueToTree(result.getChunks()),null,updates,null,result.getChunks().stream().map(RetrievedChunk::getCitation).collect(Collectors.toList()),result.getWarnings(),com.hmdp.ai.domain.run.UsageSummary.empty(0),false,null);}catch(Exception e){return NodeExecutionResult.failure(error(e),true);}}private String error(Exception e){String v=String.valueOf(e.getMessage());return v.matches("[A-Z0-9_]+")?v:"KNOWLEDGE_RETRIEVAL_FAILED";}}
